import argparse
import json
import os
import string


STUB_CONTENTS = string.Template(
    """// Generated by //kernel/lib/code_patching/hermetic_stub.py.
// Do not edit.

#include <arch/asm.hpp>
#include <lib/code_patching/asm.hpp>
#include <$header>

.text

.function $function_name, global
  .code_patching.blob $function_name, $case_suffix
.end_function
"""
)

ALIAS = string.Template(
    """
.weak $alias
.hidden $alias
$alias = $function_name
"""
)


def main():
    parser = argparse.ArgumentParser(
        description="Generate one assembly stub sized for hermetic alternatives"
    )
    parser.add_argument("--name", required=True)
    parser.add_argument("--header", required=True)
    parser.add_argument("--case-suffix", required=True)
    parser.add_argument("--metadata-file", required=True)
    parser.add_argument("--aliases", action="append", default=[])
    parser.add_argument("--depfile", required=True)
    parser.add_argument("--outfile", required=True)
    args = parser.parse_args()

    with open(args.metadata_file, encoding="utf-8") as metadata_file:
        metadata = json.load(metadata_file)

    alternatives = sorted(entry["path"] for entry in metadata)
    if not alternatives:
        parser.error("metadata contains no hermetic alternatives")

    max_size = max(os.path.getsize(path) for path in alternatives)

    with open(args.depfile, "w", encoding="utf-8") as depfile:
        depfile.write(f"{args.outfile}: {' '.join(alternatives)}\n")

    with open(args.outfile, "w", encoding="utf-8") as stub:
        stub.write(
            STUB_CONTENTS.substitute(
                header=args.header,
                function_name=args.name,
                case_suffix=args.case_suffix,
            )
        )
        for alias in args.aliases:
            stub.write(ALIAS.substitute(alias=alias, function_name=args.name))


if __name__ == "__main__":
    main()
